import re,sys,glob
seqs=[]
for fn in sys.argv[1:]:
    for line in open(fn):
        m=re.match(r'\s*<token (.*)/>\s*$',line)
        if m:
            seqs.append(re.findall(r'([A-Za-z0-9_-]+)=',m.group(1)))
succ={}; nodes=[]
for s in seqs:
    for a in s:
        if a not in succ: succ[a]=set(); nodes.append(a)
    for i in range(len(s)):
        for j in range(i+1,len(s)):
            succ[s[i]].add(s[j])
# topological: repeatedly pick node with no remaining predecessor
pred={n:set() for n in nodes}
for a in nodes:
    for b in succ[a]: pred[b].add(a)
out=[]; rem=set(nodes)
while rem:
    cands=sorted([n for n in rem if not (pred[n]&rem)])
    if not cands:
        out.append("CYCLE:"+",".join(sorted(rem))); break
    n=cands[0]; out.append(n); rem.discard(n)
print(" ".join(out))
PYEOF
